import { canonicalize, hashCanonical, type GoldenEvent, type ChainRecord } from './index.js';

export type AppendStatus = 'APPENDED' | 'IDEMPOTENT_REPLAY';
export type AppendResult = { status: AppendStatus; event_id?: string };
export type EvidenceRecord = { evidence_id:string; content_hash:string; parent_evidence_ids:string[]; [key:string]:unknown };
export type StoreSnapshot = {
  events: GoldenEvent[];
  evidence: EvidenceRecord[];
  versions: Record<string,unknown>;
  commands: Array<[string,string]>;
  chain: ChainRecord[];
  lineage: Array<{id:string;parents:string[]}>;
  certifications: Array<[string,unknown]>;
};

function fingerprint(value: unknown): string { return canonicalize(value); }
function clone<T>(value:T):T { return JSON.parse(JSON.stringify(value)); }

export class GovernanceStore {
  private events: GoldenEvent[] = [];
  private evidence = new Map<string,EvidenceRecord>();
  private versions = new Map<string,unknown>();
  private commandFingerprints = new Map<string,string>();
  private eventFingerprints = new Map<string,string>();
  private chain: ChainRecord[] = [];
  private lineage = new Map<string,{id:string;parents:string[]}>();
  private certifications = new Map<string,unknown>();

  appendEvent(event: GoldenEvent, commandId: string): AppendResult {
    const payload:any={...event}; delete payload.event_hash;
    if(hashCanonical(payload)!==event.event_hash) throw new Error(`event self-hash mismatch:${event.event_id}`);
    const fp=fingerprint(event);
    const priorCommand=this.commandFingerprints.get(commandId);
    if(priorCommand!==undefined){
      if(priorCommand!==fp) throw new Error('idempotency key conflict');
      return {status:'IDEMPOTENT_REPLAY',event_id:event.event_id};
    }
    const priorEvent=this.eventFingerprints.get(event.event_id);
    if(priorEvent!==undefined){
      if(priorEvent!==fp) throw new Error('immutable event conflict');
      this.commandFingerprints.set(commandId,fp);
      return {status:'IDEMPOTENT_REPLAY',event_id:event.event_id};
    }
    const aggregate=this.events.filter(e=>e.aggregate_id===event.aggregate_id);
    const expected=aggregate.length===0?1:Math.max(...aggregate.map(e=>e.aggregate_version))+1;
    if(event.aggregate_version!==expected){
      if(aggregate.some(e=>e.aggregate_version===event.aggregate_version)) throw new Error('aggregate version conflict');
      throw new Error(`expected aggregate version ${expected}`);
    }
    this.events.push(clone(event));
    this.eventFingerprints.set(event.event_id,fp);
    this.commandFingerprints.set(commandId,fp);
    return {status:'APPENDED',event_id:event.event_id};
  }

  appendEvidence(record: EvidenceRecord): AppendResult {
    const fp=fingerprint(record);
    const prior=this.evidence.get(record.evidence_id);
    if(prior){
      if(fingerprint(prior)!==fp) throw new Error('immutable evidence conflict');
      return {status:'IDEMPOTENT_REPLAY'};
    }
    this.evidence.set(record.evidence_id,clone(record));
    return {status:'APPENDED'};
  }

  pinVersion(ref:string, record:unknown):AppendResult {
    const prior=this.versions.get(ref);
    if(prior!==undefined){
      if(fingerprint(prior)!==fingerprint(record)) throw new Error('immutable version conflict');
      return {status:'IDEMPOTENT_REPLAY'};
    }
    this.versions.set(ref,clone(record));
    return {status:'APPENDED'};
  }

  eventsByCorrelation(correlationId:string):GoldenEvent[]{
    return this.events.filter(e=>e.correlation_id===correlationId).sort((a,b)=>a.aggregate_version-b.aggregate_version).map(clone);
  }
  evidenceRecords():EvidenceRecord[]{ return [...this.evidence.values()].map(clone); }
  versionRecords():Record<string,unknown>{ return Object.fromEntries([...this.versions.entries()].map(([k,v])=>[k,clone(v)])); }
  appendChainRecord(record:ChainRecord):AppendResult {
    const prior=this.chain.find(x=>x.ordinal===record.ordinal||x.event_id===record.event_id);
    if(prior){ if(fingerprint(prior)!==fingerprint(record)) throw new Error('immutable chain conflict'); return {status:'IDEMPOTENT_REPLAY'}; }
    this.chain.push(clone(record));
    return {status:'APPENDED'};
  }
  chainRecords():ChainRecord[]{ return this.chain.map(clone); }
  appendLineageNode(node:{id:string;parents:string[]}):AppendResult {
    const prior=this.lineage.get(node.id);
    if(prior){ if(fingerprint(prior)!==fingerprint(node)) throw new Error('immutable lineage conflict'); return {status:'IDEMPOTENT_REPLAY'}; }
    this.lineage.set(node.id,clone(node));
    return {status:'APPENDED'};
  }
  lineageNodes(){ return [...this.lineage.values()].map(clone); }
  appendCertification(record:{certification_id:string;[key:string]:unknown}):AppendResult {
    const prior=this.certifications.get(record.certification_id);
    if(prior!==undefined){ if(fingerprint(prior)!==fingerprint(record)) throw new Error('immutable certification conflict'); return {status:'IDEMPOTENT_REPLAY'}; }
    this.certifications.set(record.certification_id,clone(record));
    return {status:'APPENDED'};
  }
  certificationRecord(id:string){ const v=this.certifications.get(id); return v===undefined?null:clone(v); }

  snapshot():StoreSnapshot {
    return {events:this.events.map(clone),evidence:this.evidenceRecords(),versions:this.versionRecords(),commands:[...this.commandFingerprints.entries()],chain:this.chainRecords(),lineage:this.lineageNodes(),certifications:[...this.certifications.entries()].map(([k,v])=>[k,clone(v)])};
  }
  static fromSnapshot(snapshot:StoreSnapshot):GovernanceStore {
    const store=new GovernanceStore();
    for(const ev of snapshot.events){
      const fp=fingerprint(ev); store.events.push(clone(ev)); store.eventFingerprints.set(ev.event_id,fp);
    }
    for(const ev of snapshot.evidence) store.evidence.set(ev.evidence_id,clone(ev));
    for(const [k,v] of Object.entries(snapshot.versions)) store.versions.set(k,clone(v));
    for(const [k,v] of snapshot.commands) store.commandFingerprints.set(k,v);
    for(const c of snapshot.chain ?? []) store.chain.push(clone(c));
    for(const n of snapshot.lineage ?? []) store.lineage.set(n.id,clone(n));
    for(const [k,v] of snapshot.certifications ?? []) store.certifications.set(k,clone(v));
    return store;
  }
}

import type { GoldenEvent } from './index.js';
import { GovernanceStore, type AppendResult } from './persistence.js';

type TransitionDecision = {allowed:boolean;reason?:string;transition_id?:string;missing_guards?:string[]};
type TransitionAuthorizer = (policy:unknown,from:string,to:string,eventType:string,satisfiedGuards:Set<string>)=>TransitionDecision;
type EligibilityEvaluator = (worker:any,context?:{aiRecommendation?:string})=>{worker_id:string;decision:string;predicate_results:Record<string,boolean>;decision_hash:string};

export type TransitionCommand = {
  command_id:string;
  from:string;
  to:string;
  event:GoldenEvent;
  satisfied_guards:string[];
};

export class CLP001Adapter {
  constructor(
    private readonly store:GovernanceStore,
    private readonly transitionPolicy:unknown,
    private readonly domain:{authorizeTransition:TransitionAuthorizer;evaluateEligibility:EligibilityEvaluator}
  ){}

  executeTransition(command:TransitionCommand):AppendResult {
    const auth=this.domain.authorizeTransition(this.transitionPolicy,command.from,command.to,command.event.event_type,new Set(command.satisfied_guards));
    if(!auth.allowed) throw new Error(`transition denied: ${auth.reason ?? 'UNKNOWN'}${auth.missing_guards?.length?`:${auth.missing_guards.join(',')}`:''}`);
    return this.store.appendEvent(command.event,command.command_id);
  }

  evaluateWorker(worker:any,context?:{aiRecommendation?:string}){
    return this.domain.evaluateEligibility(worker,context);
  }

  appendEvidence(record:any){ return this.store.appendEvidence(record); }
  appendLineageNode(node:{id:string;parents:string[]}){ return this.store.appendLineageNode(node); }
  appendCertification(record:{certification_id:string;[key:string]:unknown}){ return this.store.appendCertification(record); }
  pinVersion(ref:string,record:unknown){ return this.store.pinVersion(ref,record); }
  getEvents(correlationId:string){ return this.store.eventsByCorrelation(correlationId); }
  getEvidence(){ return this.store.evidenceRecords(); }
  getLineage(){ return this.store.lineageNodes(); }
  getCertification(id:string){ return this.store.certificationRecord(id); }
  getCaseState(correlationId:string){ const events=this.store.eventsByCorrelation(correlationId); return events.at(-1)?.decision ?? null; }
  snapshot(){ return this.store.snapshot(); }
}

import { hashCanonical, verifyEventChain } from './index.js';

function validatePersistedLineage(nodes:Array<{id:string;parents:string[]}>) {
  const ids=new Set(nodes.map(n=>n.id));
  const missing:string[]=[];
  for(const n of nodes) for(const p of n.parents) if(!ids.has(p)) missing.push(`${n.id}->${p}`);
  return {valid:missing.length===0,missing};
}

export function replayPersistedCase(correlationId:string,store:GovernanceStore){
  const events=store.eventsByCorrelation(correlationId);
  if(!events.length) throw new Error('correlation id not found');
  for(let i=0;i<events.length;i++){
    const e=events[i];
    const payload:any={...e}; delete payload.event_hash;
    if(hashCanonical(payload)!==e.event_hash) throw new Error(`event self-hash mismatch:${e.event_id}`);
    if(e.aggregate_version!==i+1) throw new Error('non-monotonic aggregate version');
    if(i===0&&e.causation_event_id!==null) throw new Error('first event causation must be null');
    if(i>0&&e.causation_event_id!==events[i-1].event_id) throw new Error('causation chain broken');
  }
  const eventIds=new Set(events.map(e=>e.event_id));
  const chain=store.chainRecords().filter(c=>eventIds.has(c.event_id));
  const chainCheck=verifyEventChain(events,chain);
  if(!chainCheck.valid) throw new Error(`event chain invalid:${chainCheck.errors.join('|')}`);

  const evidence=store.evidenceRecords();
  const evidenceIds=new Set(evidence.map(e=>e.evidence_id));
  for(const ev of evidence){
    if('evidence_class' in ev && 'evidence_type' in ev && 'content' in ev){
      const payload={evidence_id:ev.evidence_id,evidence_class:ev.evidence_class,evidence_type:ev.evidence_type,content:ev.content,parent_evidence_ids:ev.parent_evidence_ids};
      if(hashCanonical(payload)!==ev.content_hash) throw new Error(`evidence hash mismatch:${ev.evidence_id}`);
    }
    for(const parent of ev.parent_evidence_ids) if(!evidenceIds.has(parent)) throw new Error(`missing evidence parent ${parent}`);
  }
  for(const e of events) for(const ref of e.evidence_refs) if(!evidenceIds.has(ref)) throw new Error(`missing evidence ${ref}`);

  const versions=store.versionRecords();
  const refs=new Set<string>();
  for(const e of events) for(const ref of [...e.source_refs,...e.policy_refs]) refs.add(ref);
  const resolved_versions:Record<string,unknown>={};
  for(const ref of refs){ if(!(ref in versions)) throw new Error(`missing pinned version ${ref}`); resolved_versions[ref]=versions[ref]; }

  const lineage_nodes=store.lineageNodes();
  const lineage=validatePersistedLineage(lineage_nodes);
  if(!lineage.valid) throw new Error(`lineage invalid:${lineage.missing.join('|')}`);
  const result={correlation_id:correlationId,final_state:events.at(-1)?.decision==='CLOSED'?'CLOSED':'UNKNOWN',events,evidence,resolved_versions,event_chain_root:chainCheck.root_hash,lineage_nodes};
  return {...result,replay_hash:hashCanonical(result)};
}
